// ---------- AUTH ----------
function authErrorMessage(error, flow) {
  const code = String(error?.code || '');
  if (code === 'auth/unauthorized-domain') {
    return 'This site is not authorized for sign-in. Add bobby-clone.codmpanda.pages.dev in Firebase Authentication > Settings > Authorized domains.';
  }
  if (code === 'auth/operation-not-allowed') {
    return flow === 'google'
      ? 'Google sign-in is disabled in Firebase Authentication. Enable the Google provider.'
      : 'Email and password sign-in is disabled in Firebase Authentication. Enable the Email/Password provider.';
  }
  if (code === 'auth/account-exists-with-different-credential') {
    return 'This email already uses another sign-in method. Sign in with the method already linked to your CODMPanda account; accounts will not be linked automatically.';
  }
  if (code === 'auth/email-already-in-use') {
    return 'An account already exists with this email. Use its existing sign-in method so your CODMPanda account and data stay connected.';
  }
  if (code === 'auth/invalid-email') return 'Enter a valid email address.';
  if (code === 'auth/weak-password') return 'Choose a password with at least 6 characters.';
  if (['auth/invalid-credential', 'auth/invalid-login-credentials', 'auth/wrong-password', 'auth/user-not-found'].includes(code)) {
    return 'Email or password is incorrect. Check your details or use Forgot password.';
  }
  if (code === 'auth/too-many-requests') return 'Too many attempts. Wait a little and try again.';
  if (code === 'auth/network-request-failed') return 'Network error. Check your connection and try again.';
  if (code === 'auth/popup-closed-by-user') return 'Google sign-in was cancelled. You can try again.';
  if (code === 'auth/invalid-api-key') return 'Firebase authentication configuration is invalid. Please contact the CODMPanda admin.';
  return 'Sign-in failed. Please try again.' + (code ? ' (' + code + ')' : '');
}

function setEmailAuthStatus(message, isError = false) {
  const status = document.getElementById('email-auth-status');
  if (!status) return;
  status.textContent = message || '';
  status.style.color = isError ? '#ff8a80' : '#a3e635';
}

function readEmailAuthFields() {
  return {
    email: String(document.getElementById('auth-email')?.value || '').trim(),
    password: String(document.getElementById('auth-password')?.value || '')
  };
}

const GOOGLE_CLIENT_ID = "604146891375-ae5bhcm2nd2f59f0npp3en6setthjg1s.apps.googleusercontent.com";
let gisInitialized = false;
let gisPromptRequested = false;
let gisButtonRenderRetried = false;

async function waitForGIS() {
  const ready = () => !!(
    window.google?.accounts?.id?.initialize &&
    window.google?.accounts?.id?.renderButton &&
    window.google?.accounts?.id?.prompt
  );
  if (ready()) return;
  // Mobile networks can load the GIS library slowly; wait long enough to avoid
  // leaving the official button container empty after a brief load delay.
  for (let attempt = 0; attempt < 300; attempt++) {
    await new Promise(resolve => setTimeout(resolve, 100));
    if (ready()) return;
  }
  throw new Error('Google Identity Services did not load.');
}

function renderOfficialGISButton() {
  const target = document.getElementById('google-signin-btn');
  const gis = window.google?.accounts?.id;
  if (!target || !gis?.renderButton) return false;
  if (target.dataset.gisRendered === '1') return true;

  target.style.display = 'flex';
  target.style.alignItems = 'center';
  target.style.justifyContent = 'center';
  target.style.minHeight = '44px';
  target.style.width = '100%';
  target.replaceChildren();

  try {
    // Render Google's own light/white button; never substitute custom button markup.
    gis.renderButton(target, {
      theme: 'outline',
      size: 'large',
      text: 'signin_with',
      shape: 'pill',
      logo_alignment: 'left',
      width: Math.min(340, Math.max(240, Math.floor(target.getBoundingClientRect().width || 340)))
    });
    target.dataset.gisRendered = '1';

    // Recover once if GIS returned before its button iframe was attached to the DOM.
    window.setTimeout(() => {
      if (!target.isConnected || target.querySelector('iframe, [role="button"]') || gisButtonRenderRetried) return;
      gisButtonRenderRetried = true;
      target.removeAttribute('data-gis-rendered');
      target.replaceChildren();
      try {
        gis.renderButton(target, {
          theme: 'outline',
          size: 'large',
          text: 'signin_with',
          shape: 'pill',
          logo_alignment: 'left',
          width: Math.min(340, Math.max(240, Math.floor(target.getBoundingClientRect().width || 340)))
        });
        target.dataset.gisRendered = '1';
      } catch (error) {
        target.removeAttribute('data-gis-rendered');
        console.error('[CODMPanda] Google button retry failed:', error);
      }
    }, 900);
    return true;
  } catch (error) {
    target.removeAttribute('data-gis-rendered');
    console.error('[CODMPanda] Google button render failed:', error);
    return false;
  }
}

function initGIS() {
  const gis = window.google?.accounts?.id;
  if (!gis?.initialize || !gis?.renderButton || !gis?.prompt) return false;

  if (!gisInitialized) {
    gis.initialize({
      client_id: GOOGLE_CLIENT_ID,
      callback: handleGISResponse,
      auto_select: false,
      cancel_on_tap_outside: true,
      use_fedcm_for_prompt: true,
      use_fedcm_for_button: true
    });
    gisInitialized = true;
    console.log('[CODMPanda] Google Identity Services initialized for One Tap and the official button.');
  }

  renderOfficialGISButton();
  return true;
}

async function requestGISPrompt() {
  try {
    await waitForGIS();
    if (!initGIS()) throw new Error('Google Identity Services could not be initialized.');
    // The browser controls FedCM's prompt presentation. This call never starts an OAuth redirect.
    if (gisPromptRequested) return;
    gisPromptRequested = true;
    window.google.accounts.id.prompt(function(notification) {
      if (notification?.isSkippedMoment?.()) {
        console.info('[CODMPanda] Google One Tap was skipped by the browser or user.');
      }
    });
  } catch (error) {
    console.error('[CODMPanda] Google One Tap initialization failed; official button remains the only supported fallback:', error);
  }
}

async function handleGISResponse(response) {
  try {
    if (!response?.credential) throw new Error('Google did not return a sign-in credential.');
    const credential = GoogleAuthProvider.credential(response.credential);
    const result = await signInWithCredential(auth, credential);
    console.log('[CODMPanda] GIS Firebase sign-in succeeded:', result.user.email);
    setEmailAuthStatus('');
    toast('Signed in!', 'success');
  } catch (error) {
    console.error('[CODMPanda] GIS Firebase credential sign-in failed:', error?.code || error);
    const message = authErrorMessage(error, 'google');
    setEmailAuthStatus(message, true);
    toast(message, 'error', 5000);
  }
}

async function handleEmailSignIn() {
  const { email, password } = readEmailAuthFields();
  if (!email || !password) {
    setEmailAuthStatus('Enter your email and password.', true);
    return;
  }
  try {
    setEmailAuthStatus('Signing in…');
    await signInWithEmailAndPassword(auth, email, password);
    setEmailAuthStatus('');
    toast('Signed in!', 'success');
  } catch (error) {
    const message = authErrorMessage(error, 'email');
    setEmailAuthStatus(message, true);
    console.error('[CODMPanda] Email sign-in failed:', error?.code || error);
  }
}

async function handleEmailSignUp() {
  const { email, password } = readEmailAuthFields();
  if (!email || !password) {
    setEmailAuthStatus('Enter an email and choose a password.', true);
    return;
  }
  if (password.length < 6) {
    setEmailAuthStatus('Choose a password with at least 6 characters.', true);
    return;
  }
  try {
    setEmailAuthStatus('Creating your account…');
    await createUserWithEmailAndPassword(auth, email, password);
    setEmailAuthStatus('');
    toast('Account created!', 'success');
    // onAuthStateChanged + ensureUserProfile creates one profile for this new UID.
  } catch (error) {
    const message = authErrorMessage(error, 'signup');
    setEmailAuthStatus(message, true);
    console.error('[CODMPanda] Email sign-up failed:', error?.code || error);
  }
}

async function handlePasswordReset() {
  const email = String(document.getElementById('auth-email')?.value || '').trim();
  if (!email) {
    setEmailAuthStatus('Enter your email address first, then tap Forgot password.', true);
    return;
  }
  try {
    await sendPasswordResetEmail(auth, email);
    setEmailAuthStatus('Password reset email sent. Check your inbox and spam folder.');
    toast('Password reset email sent.', 'success');
  } catch (error) {
    const message = authErrorMessage(error, 'reset');
    setEmailAuthStatus(message, true);
    console.error('[CODMPanda] Password reset failed:', error?.code || error);
  }
}

function providerLinkErrorMessage(error, flow) {
  const code = String(error?.code || '');
  if (['auth/credential-already-in-use', 'auth/email-already-in-use'].includes(code)) {
    return 'That sign-in method already belongs to a different Firebase account. Nothing was merged or moved. Sign in to the account that already owns it; combining existing profiles requires a separate verified data migration.';
  }
  if (code === 'auth/provider-already-linked') {
    return 'This sign-in method is already linked to this CODMPanda account.';
  }
  if (code === 'auth/requires-recent-login') {
    return 'For security, sign out and sign back in, then try linking again.';
  }
  if (['auth/popup-blocked', 'auth/cancelled-popup-request', 'auth/popup-closed-by-user'].includes(code)) {
    return 'Google linking was cancelled or blocked. Allow popups for this site and try again.';
  }
  return authErrorMessage(error, flow);
}

function setSignInMethodsStatus(message, isError = false) {
  const status = document.getElementById('signin-methods-status');
  if (!status) return;
  status.textContent = message || '';
  status.style.color = isError ? '#ff8a80' : '#a3e635';
}

async function linkEmailPasswordToCurrentAccount() {
  const user = auth.currentUser;
  const email = String(document.getElementById('link-email-address')?.value || '').trim();
  const password = String(document.getElementById('link-email-password')?.value || '');
  const button = document.getElementById('link-email-submit');

  if (!user) {
    setSignInMethodsStatus('Your session ended. Sign in again before linking a method.', true);
    return;
  }
  if (!email || !password) {
    setSignInMethodsStatus('Enter the email address and password you want to link.', true);
    return;
  }
  if (password.length < 6) {
    setSignInMethodsStatus('The password must be at least 6 characters.', true);
    return;
  }

  if (button) { button.disabled = true; button.textContent = 'Linking…'; }
  setSignInMethodsStatus('Verifying the email/password credential…');
  try {
    const credential = EmailAuthProvider.credential(email, password);
    const result = await linkWithCredential(user, credential);
    State.user = result.user;
    toast('Email/password linked to this CODMPanda account.', 'success');
    openSignInMethodsSheet();
  } catch (error) {
    const message = providerLinkErrorMessage(error, 'email');
    setSignInMethodsStatus(message, true);
    console.error('[CODMPanda] Email provider linking failed:', error?.code || error);
    toast(message, 'error', 6000);
    if (button) { button.disabled = false; button.textContent = 'Link email + password'; }
  }
}

async function linkGoogleToCurrentAccount() {
  const user = auth.currentUser;
  const button = document.getElementById('link-google-provider-btn');
  if (!user) {
    setSignInMethodsStatus('Your session ended. Sign in again before linking a method.', true);
    return;
  }

  if (button) { button.disabled = true; button.innerHTML = '<span class="spinner"></span>'; }
  setSignInMethodsStatus('Opening Google securely…');
  try {
    const provider = new GoogleAuthProvider();
    provider.setCustomParameters({ prompt: 'select_account' });
    const result = await linkWithPopup(user, provider);
    State.user = result.user;
    toast('Google linked to this CODMPanda account.', 'success');
    openSignInMethodsSheet();
  } catch (error) {
    const message = providerLinkErrorMessage(error, 'google');
    setSignInMethodsStatus(message, true);
    console.error('[CODMPanda] Google provider linking failed:', error?.code || error);
    toast(message, 'error', 6000);
    if (button) {
      button.disabled = false;
      button.innerHTML = '<span aria-hidden="true" class="font-black text-base">G</span><span>Link Google account</span>';
    }
  }
}


function openSignInMethodsSheet() {
  const user = auth.currentUser;
  if (!user) {
    toast('Sign in before managing sign-in methods.', 'error');
    return;
  }

  const linkedProviderIds = new Set((user.providerData || []).map(provider => provider.providerId));
  const hasEmail = linkedProviderIds.has('password');
  const hasGoogle = linkedProviderIds.has('google.com');

  openSheet(`
    <div id="signin-methods-sheet" class="space-y-4">
      <p class="text-xs text-gray-400 leading-relaxed">
        Manage sign-in methods for <span class="text-white font-semibold">${esc(user.email || 'this account')}</span>.
        Linked methods use this account's existing CODMPanda UID and progress. If a credential already belongs to another Firebase account, linking stops; accounts and data are never merged automatically.
      </p>
      <div class="rounded-xl border border-border divide-y divide-border">
        <div class="flex items-center justify-between gap-3 px-3 py-3">
          <span class="text-sm font-semibold">Email + password</span>
          <span class="text-[10px] font-bold ${hasEmail ? 'text-green-400' : 'text-gray-500'}">${hasEmail ? 'LINKED' : 'NOT LINKED'}</span>
        </div>
        <div class="flex items-center justify-between gap-3 px-3 py-3">
          <span class="text-sm font-semibold">Google</span>
          <span class="text-[10px] font-bold ${hasGoogle ? 'text-green-400' : 'text-gray-500'}">${hasGoogle ? 'LINKED' : 'NOT LINKED'}</span>
        </div>
      </div>
      ${!hasEmail ? `
        <form id="link-email-form" class="space-y-3">
          <div class="text-xs font-bold text-gray-300">Link email + password</div>
          <div>
            <label for="link-email-address" class="block mb-1 text-[11px] text-gray-500">Email address</label>
            <input id="link-email-address" type="email" autocomplete="email" inputmode="email" placeholder="you@example.com" required />
          </div>
          <div>
            <label for="link-email-password" class="block mb-1 text-[11px] text-gray-500">Password (at least 6 characters)</label>
            <input id="link-email-password" type="password" autocomplete="current-password" minlength="6" required />
          </div>
          <button id="link-email-submit" type="submit" class="btn-press w-full py-3 rounded-xl bg-primary text-sm font-bold">Link email + password</button>
        </form>
      ` : '<p class="text-xs text-green-400">Email/password is already linked to this account.</p>'}
      ${!hasGoogle ? `
        <div class="space-y-2">
          <div class="text-xs font-bold text-gray-300">Link Google</div>
          <button id="link-google-provider-btn" type="button" class="btn-press w-full min-h-[44px] rounded-xl border border-border bg-white text-gray-800 font-semibold text-sm flex items-center justify-center gap-3 disabled:opacity-60">
            <span aria-hidden="true" class="font-black text-base">G</span>
            <span>Link Google account</span>
          </button>
          <p class="text-[10px] text-gray-500">Choose the Google account you want to use for this same CODMPanda profile.</p>
        </div>
      ` : '<p class="text-xs text-green-400">Google is already linked to this account.</p>'}
      <div id="signin-methods-status" role="status" aria-live="polite" class="text-xs leading-relaxed" style="min-height:16px;color:#a3e635;"></div>
      <button type="button" onclick="closeSheet()" class="btn-press w-full py-3 rounded-xl border border-border bg-cardAlt text-sm font-semibold">Done</button>
    </div>
  `, 'Sign-in Methods');

  const emailForm = document.getElementById('link-email-form');
  if (emailForm) {
    emailForm.addEventListener('submit', event => {
      event.preventDefault();
      linkEmailPasswordToCurrentAccount();
    });
  }

  const googleLinkButton = document.getElementById('link-google-provider-btn');
  if (googleLinkButton) {
    googleLinkButton.addEventListener('click', linkGoogleToCurrentAccount);
  }
}

