  const sep = url.includes('?') ? '&' : '?';
  const finalUrl = url +
    sep + 'checkout[email]=' + encodeURIComponent(email) +
    '&checkout[custom][uid]=' + encodeURIComponent(uid);

  toast('Opening checkout...', 'info', 1500);

  // Open Lemon Squeezy checkout in new tab
