// PART 3: FRIEND DMs
// ============================================

async function openDMThread(friendUid, friendIgn) {
  // Set the target here as well as in the redesign wrapper so every entry point
  // (friends list, inbox row, or New Chat) gets correct DM presence/block state.
  window.__cpCurrentDMTarget = { uid: String(friendUid || ''), ign: String(friendIgn || 'Player') };
  // Create or get chat ID (sorted so both users share same ID)
  const chatId = [State.user.uid, friendUid].sort().join('_');

  openSheet(`
    <div class="flex flex-col" style="height: 70vh;">
      <div id="dm-messages" class="flex-1 overflow-y-auto mb-3 space-y-2 pb-3">
        <div class="text-center py-6"><div class="spinner mx-auto"></div></div>
      </div>
      <div class="sticky bottom-0 bg-[#0a0a0a] pt-3 border-t border-border">
        <div class="flex gap-2 items-center">
          <button id="dm-image-pick" type="button" title="Attach image" aria-label="Attach image" class="w-11 h-11 rounded-xl border border-border text-gray-300 flex items-center justify-center flex-shrink-0">＋</button>
          <input id="dm-image-file" type="file" accept="image/jpeg,image/png,image/webp,image/gif" class="hidden" />
          <input id="dm-input" type="text" placeholder="Message ${esc(friendIgn)}..." class="flex-1 min-w-0" maxlength="500" />
          <button id="dm-send" class="btn-press w-11 h-11 rounded-xl bg-primary flex items-center justify-center flex-shrink-0">
            <i data-lucide="send" class="w-5 h-5 text-white"></i>
          </button>
        </div>
        <div id="dm-upload-status" class="text-[10px] text-gray-500 mt-2 min-h-3"></div>
      </div>
    </div>
  `, `💬 ${esc(friendIgn)}`);

  // Focus the composer immediately; opening a thread should not wait for Firestore.
  const messagesContainer = document.getElementById('dm-messages');
  const immediateInput = document.getElementById('dm-input');
  if (immediateInput) setTimeout(() => { immediateInput.focus({preventScroll:true}); }, 0);

  const loadMessages = async () => {
    try {
      // Firestore rules authorize only conversations where the signed-in user
      // is sender or recipient. Query each side explicitly instead of querying
      // by chatId alone (which caused normal-account permission errors).
      const [sentSnap, receivedSnap] = await inboxWithTimeout(Promise.all([
        getDocs(query(collection(db, 'messages'), where('chatId', '==', chatId), where('fromUid', '==', State.user.uid), limit(100))),
        getDocs(query(collection(db, 'messages'), where('chatId', '==', chatId), where('toUid', '==', State.user.uid), limit(100)))
      ]), 'Chat messages');
      if (document.getElementById('dm-messages') !== messagesContainer) return;
      const docsById = new Map();
      sentSnap.forEach(d => docsById.set(d.id, d));
      receivedSnap.forEach(d => docsById.set(d.id, d));
      const snap = { empty: docsById.size === 0, forEach: fn => docsById.forEach(fn) };

if (snap.empty) {
  messagesContainer.innerHTML = `
    <div class="text-center py-8">
      <div class="text-3xl mb-2">💬</div>
      <div class="text-xs text-gray-500">Start the conversation</div>
    </div>
  `;
  return;
}

const messages = [];
snap.forEach(d => messages.push({ id: d.id, ...d.data() }));

// Sort client-side by createdAt
messages.sort((a, b) => {
  const aT = a.createdAt?.seconds || 0;
  const bT = b.createdAt?.seconds || 0;
  return aT - bT;
});

      messagesContainer.innerHTML = messages.map(m => {
        const isMine = m.fromUid === State.user.uid;
        const body = m.imageUrl
          ? `<a href="${esc(m.imageUrl)}" target="_blank" rel="noopener noreferrer"><img src="${esc(m.imageUrl)}" alt="Shared image" loading="lazy" style="display:block;max-width:220px;max-height:260px;border-radius:10px;object-fit:contain"></a>${m.text ? `<div class="text-xs whitespace-pre-wrap break-words mt-2">${esc(m.text)}</div>` : ''}`
          : `<div class="text-xs whitespace-pre-wrap break-words">${esc(m.text || '')}</div>`;
        const status = isMine ? (m.readAt ? 'Read' : 'Sent') : '';
        return `
          <div class="flex ${isMine ? 'justify-end' : 'justify-start'}" data-dm-message-id="${esc(m.id)}">
            <div class="max-w-[82%] ${isMine ? 'bg-primary text-white' : 'bg-card border border-border'} rounded-2xl px-3 py-2">
              ${body}
              <div class="text-[8px] ${isMine ? 'text-white/70' : 'text-gray-500'} mt-1 text-right">${cpDateTimeHTML(m.createdAt)} <span data-dm-status>${status ? ' · '+status : ''}</span></div>
            </div>
          </div>
        `;
      }).join('');

      // Receiver marks incoming messages read; the rules only permit the recipient to set readAt.
      messages.filter(m => m.toUid === State.user.uid && !m.readAt).forEach(m => {
        updateDoc(doc(db, 'messages', m.id), { readAt: serverTimestamp() }).catch(() => {});
      });
      messagesContainer.scrollTop = messagesContainer.scrollHeight;
    } catch (e) {
      console.error('DM load error:', e);
      messagesContainer.innerHTML = '<div class="text-center py-6 text-red-400 text-xs">Failed to load messages</div>';
    }
  };

  // Send message
  const sendMessage = async () => {
    const input = document.getElementById('dm-input');
    const text = input.value.trim();
    if (!text) return;

    input.value = '';
    input.disabled = true;

    try {
      await addDoc(collection(db, 'messages'), {
        chatId,
        fromUid: State.user.uid,
        fromIgn: State.profile.ign,
        toUid: friendUid,
        toIgn: friendIgn,
        text,
        createdAt: serverTimestamp()
      });

      // Notify recipient
      try {
        await sendNotificationToUser(
          friendUid,
          `💬 ${State.profile.ign}`,
          text.length > 60 ? text.slice(0, 60) + '...' : text,
          { type: 'dm', chatId }
        );
      } catch (e) { /* silent */ }

      await loadMessages();
    } catch (e) {
      console.error(e);
      toast('Send failed', 'error');
    } finally {
      input.disabled = false;
      input.focus();
    }
  };

  document.getElementById('dm-send').onclick = sendMessage;
  document.getElementById('dm-input').onkeypress = (e) => {
    if (e.key === 'Enter') sendMessage();
  };

  // DM images are resized/compressed in the browser and stored as Base64 in Firestore.
  // Retry with smaller dimensions/lower JPEG quality until the payload is safely below 700 KB.
  // Base64 strings plus message metadata must remain below Firestore's 1 MiB document limit.
  async function compressDMImage(file) {
    const attempts = [
      [700, 0.55],
      [600, 0.50],
      [500, 0.45],
      [400, 0.40],
      [320, 0.35],
      [240, 0.30]
    ];
    for (const [maxSize, quality] of attempts) {
      const data = await compressImage(file, maxSize, quality);
      if (data && data.startsWith('data:image/jpeg;base64,') && data.length <= 700000) {
        return data;
      }
    }
    throw new Error('This image is still too large after compression. Try a smaller image.');
  }

  const imagePick = document.getElementById('dm-image-pick');
  const imageFile = document.getElementById('dm-image-file');
  const uploadStatus = document.getElementById('dm-upload-status');
  if (imagePick && imageFile) {
    imagePick.onclick = () => imageFile.click();
    imageFile.onchange = async () => {
      const file = imageFile.files?.[0];
      if (!file) return;
      if (!/^image\/(jpeg|png|webp|gif)$/.test(file.type)) {
        toast('Choose a JPG, PNG, WEBP, or GIF image', 'error');
        imageFile.value = '';
        return;
      }
      if (file.size > 10 * 1024 * 1024) {
        toast('Choose an image smaller than 10 MB', 'error');
        imageFile.value = '';
        return;
      }
      imagePick.disabled = true;
      imageFile.disabled = true;
      if (uploadStatus) uploadStatus.textContent = 'Compressing image…';
      try {
        const imageData = await compressDMImage(file);
        if (uploadStatus) uploadStatus.textContent = 'Sending image…';
        await addDoc(collection(db, 'messages'), {
          chatId,
          fromUid: State.user.uid,
          fromIgn: State.profile.ign,
          toUid: friendUid,
          toIgn: friendIgn,
          text: '',
          type: 'image',
          imageUrl: imageData,
          createdAt: serverTimestamp()
        });
        try {
          await sendNotificationToUser(friendUid, `💬 ${State.profile.ign}`, '📷 Sent you an image', { type: 'dm', chatId });
        } catch (_) {}
        if (uploadStatus) uploadStatus.textContent = '';
        await loadMessages();
      } catch (e) {
        console.error('DM image compression/send failed:', e);
        toast(e.message && e.message.includes('still too large')
          ? e.message
          : 'Image failed to send. Please try another image.', 'error');
        if (uploadStatus) uploadStatus.textContent = 'Send failed';
      } finally {
        imagePick.disabled = false;
        imageFile.disabled = false;
        imageFile.value = '';
      }
    };
  }

  // Render the sheet first, then hydrate messages in the background.
  loadMessages();
  if (window.lucide) window.lucide.createIcons();
}

window.renderSkinsPanel = renderSkinsPanel;
window.openAddSkinSheet = openAddSkinSheet;
window.openTeamRegisterSheet = openTeamRegisterSheet;
window.openDMThread = openDMThread;

