function renderHomeCard(item) {
  switch (item.type) {
    case 'lobby': return renderHomeLobbyCard(item);
    case 'vault': return renderHomeVaultCard(item);
    case 'clip': return renderHomeClipCard(item);
    case 'leak': return renderHomeLeakCard(item);
    default: return '';
  }
}

