// ============================================
// PART 1: VOICE ROOM STATE
// ============================================

var voiceRoomState = {
  active: false,
  minimized: false,
  lobbyId: null,
  lobby: null,
  jitsiApi: null,
  isMuted: false,
  participants: 0
};
